def completar_grupo(apps, schema_editor):
    """Cada usuario toma como grupo la ficha (tabla grupos) de su auth.Group."""
    Usuario = apps.get_model("core", "Usuario")
    Grupo = apps.get_model("core", "Grupo")
    ficha = dict(Grupo.objects.exclude(group=None).values_list("group_id", "pk"))
    for u in Usuario.objects.prefetch_related("groups"):
        grupos = [g.pk for g in u.groups.all() if g.pk in ficha]
        if grupos:
            u.grupo_id = ficha[grupos[0]]
            u.save(update_fields=["grupo"])


